function collect(){return {insrType:el('insrType').value,prodType:el('prodType').value,I_ID:rows().map(r=>r.cells[1].firstElementChild.value),POLICY_NO:rows().map(r=>r.cells[2].firstElementChild.value.replace(/(\r)?\n/g,'\r\n'))};}
