function injectResponse(){if(!pending){note('審閱工具：需先按「匯出檔案」交接，不自動建立資料。');return;}const mode=el('response-case').value,desc=el('response-description').value,msgid=el('response-msgid').value;pending=false;cover.hidden=true;
 if(mode==='target-error'){state('ST-007');log({synthetic:true,targetResponse:{code:500,msg:desc,data:null},gap:'TODO-002：目標沒有逐列資料；不回填、不下載。',existingRowsPreserved:true});note('ST-007：目標錯誤與舊拒絕回填不相容，這不是已確認的產品 fallback。');return;}
 if(mode==='raw'){state(rows().length?'ST-002':'ST-001');note('非結構文字回應：只展示已知共用提示提取，本頁回填結果未知 TODO-006。');commonResponse(-1,desc,'');return;}
 const success=mode==='success',map={};rows().forEach(r=>{const id=r.cells[1].firstElementChild.value;map[id]=success?'已匯出':el('row-result').value;renderResult(r.cells[3],map[id]);});state(success?'ST-005':'ST-006');const fileName='DEMO_20261012.xlsx';log({synthetic:true,legacyResponse:{ErrMsg:{returnCode:success?0:1,displayMsgDescs:desc,msgid},rtnMap:map,...(success?{fileName}:{})},order:success?['回填逐列結果','BOUND-002 同視窗下載交接（未實際產檔／下載）','共用訊息完成處理']:['回填逐列结果','不下載','共用訊息完成處理']});note(success?'ST-005：合成成功資料已回填，僅記錄同視窗下載邊界。':'ST-006：合成舊拒絕資料已回填，不下載。');commonResponse(success?0:1,desc,msgid);}
function entryMessage(){const mode=el('entry-case').value,description=el('entry-description').value;let code=0,msgid='',exception='',sysid='';if(mode==='notice')code=99;if(mode==='error'){code=500;msgid='DEMO-ERROR-000001';}if(mode==='exception'){exception='合成異常原因';sysid='DEMO';}const desc=mode==='none'?'':description;
 if(el('has-bottom').checked&&el('rollback').checked){el('rollback').checked=false;note('入口回退旗標已清除，提前退出：未交底部、未警示。');return;}updateBottom(desc,code);let text='';if(exception!==''){text='異常原因:'+exception+'\n\n程式ID:'+sysid+'\n\n';}else if(code!==0&&code!==99){text='訊息說明:\n'+desc+'\n'+(msgid?'\n錯誤編號：\n'+msgid:'');}if(text)alert(text);note('合成入口情境已處理；入口與非同步訊息標點分別保留。');}
el('addBtn').addEventListener('click',addRow);el('exportBtn').addEventListener('click',exportRows);el('msg-confirm').addEventListener('click',closeMessage);el('inject-response').addEventListener('click',injectResponse);el('entry-inject').addEventListener('click',entryMessage);el('toggle-review').onclick=()=>{el('review').hidden=!el('review').hidden;};el('reset-review').onclick=()=>location.reload();
document.addEventListener('click',e=>{if(product.contains(e.target)&&(e.target.type==='button'||e.target.type==='submit')&&e.target!==el('msg-confirm'))clearBottom();});
el('policy-enabled').onchange=()=>document.body.classList.toggle('policy-print',el('policy-enabled').checked);
function policy(){return el('policy-enabled').checked;}
